            bid = max(66.0, highest_prev + 3.0)
        return float(min(budget, bid))

    if enough_for_all:
        if highest_prev >= 130:
            bid = 16.0
        elif highest_prev >= 80:
            bid = 22.0
        else:
            bid = 28.0
        return float(min(budget, bid))

    if enough_for_most:
        if pressured:
            bid = max(46.0, min(64.0, avg_prev * 0.55))
        else:
            if highest_prev >= 130:
                bid = 24.0
            elif highest_prev >= 80:
                bid = 31.0
