def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents
    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive'):
            alive.append((oid, o))

    # If no opponents, bid conservatively
    if not alive:
        return min(my_status['budget'], DAILY_SALARY * 0.35)

    # Estimate likely competition using yesterday trace bids
    # (Only immediate reaction: use previous_trace from yesterday.)
    prev_bids = []
    for oid, o in alive:
        prev = o.get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Target bid based on yesterday's max bid pressure
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Supply-to-water conversion: if supply is high enough, lower bids can still secure.
    # But we don't know exact allocation mechanics; we use a robust bidding band.
    # Normalize by how many WATER_REQ units supply can cover.
    units = supply / float(WATER_REQ)

    # Base aggression: if Cindy was aggressive yesterday, we must match a fraction to avoid losing.
    # Cindy survived 10 days with very high bids in the meta-round context.
    # We infer that high bids correlate with survival, so we bid near the top-but-not-max.
    if highest_prev_bid >= DAILY_SALARY * 1.2:
        # High competition: bid close to 80-90% of yesterday's max depending on our risk.
        risk = 0
        if my_status['hp'] is not None:
            if my_status['hp'] <= 2:
                risk += 2
            elif my_status['hp'] <= 4:
                risk += 1
        if my_status.get('no_water_days', 0) is not None:
            if my_status['no_water_days'] >= 2:
                risk += 1

        # If risky, bid higher; otherwise slightly lower.
        frac = 0.9 if risk >= 2 else (0.85 if risk == 1 else 0.8)
        target = highest_prev_bid * frac
    else:
        # Moderate competition: bid enough to be competitive but preserve budget.
        # Scale with supply units: higher supply allows lower bid.
        # Use a floor to avoid being too low.
        target = max(DAILY_SALARY * 0.45, highest_prev_bid * 0.75 + 2.0)
        if units >= 2.0:
            target *= 0.9

    # Additional safeguards based on our current hp and water debt
    if my_status['hp'] is not None and my_status['hp'] <= 2:
        target = max(target, DAILY_SALARY * 0.9)
    elif my_status['hp'] is not None and my_status['hp'] <= 4:
        target = max(target, DAILY_SALARY * 0.65)

    if my_status.get('no_water_days', 0) is not None and my_status['no_water_days'] >= 3:
        target = max(target, DAILY_SALARY * 0.75)

    # Ensure we don't overbid beyond budget
    budget = float(my_status['budget'])
    bid = min(budget, float(target))

    # Keep bid non-negative
    if bid < 0:
        bid = 0.0

    # If budget is extremely low, bid whatever remains (or minimal effective bid)
    if budget <= DAILY_SALARY * 0.15:
        return budget

    return bid

