    if my_current_hp <= 2: # Very low HP, bid aggressively
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    # LOW HP: Need water soon
    if my_current_hp <= 4: # Low HP, bid high
        # If opponents were bidding very high, match or slightly exceed
        if highest_prev_bid >= DAILY_SALARY * 0.8:
            return min(my_status['budget'], highest_prev_bid + 5)
        return min(my_status['budget'], DAILY_SALARY * 0.8)

    # NORMAL HP: Adjust based on opponent pressure and day
    # More aggressive towards end of the episode
    if current_day >= EPISODE_DAYS - 2: # Last few days, need to secure water
        if highest_prev_bid >= DAILY_SALARY * 0.7:
            return min(my_status['budget'], highest_prev_bid + 2)
        return min(my_status['budget'], DAILY_SALARY * 0.85)

    # Early/Mid game, normal HP
    # If opponents were bidding high, react
    if highest_prev_bid >= DAILY_SALARY * 0.6:
        # Bid slightly above their highest to win, but not too much
        return min(my_status['budget'], highest_prev_bid + 1)

